{
  "name": "blockcraft",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "A handcrafted voxel sandbox that runs in the browser.",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "three": "0.180.0"
  },
  "devDependencies": {
    "vite": "7.3.7"
  }
}

import { defineConfig } from 'vite'

export default defineConfig({
  base: './',
  build: {
    target: 'es2020',
    assetsInlineLimit: 0,
  },
  server: {
    host: '0.0.0.0',
    port: 3002,
  },
})

:root {
  --ink: #eaf2f7;
  --muted: #9fb0bd;
  --panel: rgba(10, 18, 26, 0.74);
  --panel-strong: rgba(8, 15, 22, 0.9);
  --line: rgba(255, 255, 255, 0.14);
  --green: #7ed957;
  --green-deep: #2f7d32;
  --amber: #ffc857;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  --sans: "Segoe UI", Inter, system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #0a1119;
  color: var(--ink);
  font-family: var(--sans);
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(120% 100% at 50% 45%, transparent 52%, rgba(4, 9, 14, 0.38) 100%),
    linear-gradient(to bottom, rgba(5, 10, 16, 0.16), transparent 18%, transparent 82%, rgba(5, 10, 16, 0.2));
}

#underwater {
  position: fixed;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.25s ease;
  background:
    radial-gradient(80% 60% at 50% 40%, rgba(64, 160, 220, 0.1), rgba(7, 52, 92, 0.62)),
    repeating-linear-gradient(115deg, rgba(255, 255, 255, 0.03) 0 2px, transparent 2px 9px);
  backdrop-filter: blur(1.5px) saturate(0.8);
}

#underwater.is-on {
  opacity: 1;
}

/* ---------------- overlays ---------------- */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s;
}

.overlay.is-open {
  opacity: 1;
  visibility: visible;
}

.menu-scrim {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(90% 80% at 50% 30%, rgba(8, 15, 20, 0.18), rgba(5, 9, 13, 0.72) 100%),
    linear-gradient(to bottom, rgba(5, 9, 13, 0.5), rgba(5, 9, 13, 0.25) 45%, rgba(5, 9, 13, 0.82));
  backdrop-filter: blur(3px) saturate(1.05);
}

.menu-inner {
  position: relative;
  z-index: 2;
  width: min(980px, 94vw);
  max-height: 96vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
  padding: 20px;
  animation: menu-in 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes menu-in {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.menu-header {
  text-align: center;
  margin-top: 2vh;
}

.logo {
  margin: 0;
  font-family: Impact, "Arial Black", "Segoe UI Black", sans-serif;
  font-size: clamp(58px, 11vw, 118px);
  line-height: 0.9;
  letter-spacing: 0.035em;
  text-transform: uppercase;
  color: #f7fbff;
  text-shadow:
    0 4px 0 #2e5f2c,
    0 8px 0 #1c3f1d,
    0 12px 26px rgba(0, 0, 0, 0.7),
    0 0 60px rgba(126, 217, 87, 0.25);
}

.logo span {
  color: var(--green);
  text-shadow:
    0 4px 0 #2e5f2c,
    0 8px 0 #1c3f1d,
    0 12px 26px rgba(0, 0, 0, 0.7),
    0 0 60px rgba(126, 217, 87, 0.45);
}

.tagline {
  margin: 14px 0 0;
  color: #d7e5ee;
  font-size: clamp(12px, 1.5vw, 16px);
  letter-spacing: 0.28em;
  text-transform: uppercase;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.8);
}

.menu-panel {
  width: min(460px, 100%);
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--panel);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(16px) saturate(1.15);
}

.seed-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.seed-field input {
  width: 100%;
  height: 44px;
  padding: 0 14px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(0, 0, 0, 0.32);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 15px;
  letter-spacing: 0.04em;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.seed-field input:focus {
  border-color: rgba(126, 217, 87, 0.7);
  box-shadow: 0 0 0 3px rgba(126, 217, 87, 0.15);
}

.menu-actions {
  display: flex;
  gap: 10px;
  margin-top: 14px;
}

.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: 11px;
  min-height: 46px;
  padding: 0 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  font-family: var(--sans);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.03em;
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease, border-color 0.2s;
}

.btn svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.btn-primary {
  flex: 1.25;
  background: linear-gradient(180deg, #8fe76a, #5db83d 58%, #3f932b);
  color: #0b1a0a;
  border-color: rgba(255, 255, 255, 0.28);
  box-shadow: 0 8px 24px rgba(87, 190, 62, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.45);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.25);
}

.btn-primary:hover {
  box-shadow: 0 12px 30px rgba(87, 190, 62, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}

.btn-ghost {
  flex: 1;
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(255, 255, 255, 0.14);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.24);
}

.menu-note {
  margin: 13px 2px 0;
  color: #8fa1ae;
  font-size: 11.5px;
  line-height: 1.5;
}

.controls-card {
  width: min(760px, 100%);
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 14px;
  background: rgba(8, 15, 21, 0.55);
  backdrop-filter: blur(12px);
}

.controls-card > div {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  color: #b9c8d3;
  font-size: 11px;
}

.controls-card span {
  margin-left: 4px;
  color: #8ea0ac;
  white-space: nowrap;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 21px;
  padding: 0 6px;
  border-radius: 5px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom-width: 2px;
  background: rgba(255, 255, 255, 0.08);
  color: #e8f1f7;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1;
}

.menu-footer {
  width: min(760px, 100%);
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: #7f929f;
  font-size: 10.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.menu-footer b {
  color: #b8c8d2;
  font-family: var(--mono);
  letter-spacing: 0;
  text-transform: none;
}

/* ---------------- pause ---------------- */

#pause {
  z-index: 30;
}

.pause-inner {
  position: relative;
  z-index: 2;
  width: min(420px, 90vw);
  padding: 26px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--panel-strong);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
  text-align: center;
  animation: menu-in 0.35s ease both;
}

.pause-inner h2 {
  margin: 0;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 46px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-shadow: 0 4px 0 rgba(0, 0, 0, 0.35);
}

.pause-sub {
  margin: 4px 0 20px;
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.pause-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.pause-actions .btn {
  width: 100%;
  flex: none;
}

.sens-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 20px;
  color: var(--muted);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-align: left;
}

input[type="range"] {
  width: 100%;
  height: 4px;
  appearance: none;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  border: 2px solid #0d1a11;
  background: var(--green);
  box-shadow: 0 0 0 3px rgba(126, 217, 87, 0.2);
  cursor: pointer;
}

.pause-hint {
  margin: 18px 0 0;
  color: #778a96;
  font-size: 10.5px;
}

/* ---------------- loading ---------------- */

#loading {
  z-index: 40;
  background:
    radial-gradient(80% 60% at 50% 40%, rgba(29, 55, 36, 0.55), transparent 70%),
    linear-gradient(160deg, #0c1a14, #0a1119 55%, #080d13);
}

.loader {
  width: min(420px, 84vw);
  text-align: center;
}

.loader-mark {
  width: 54px;
  height: 54px;
  margin: 0 auto 20px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  transform: rotate(45deg);
  animation: loader-spin 3.4s linear infinite;
}

.loader-mark span {
  border-radius: 3px;
  background: linear-gradient(140deg, #9cf07a, #4c9e34);
  box-shadow: 0 0 18px rgba(126, 217, 87, 0.25);
}

.loader-mark span:nth-child(2) {
  opacity: 0.55;
}
.loader-mark span:nth-child(3) {
  opacity: 0.75;
}
.loader-mark span:nth-child(4) {
  opacity: 0.35;
}

@keyframes loader-spin {
  to {
    transform: rotate(405deg);
  }
}

.loader-title {
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 34px;
  letter-spacing: 0.12em;
  color: #f2f8f4;
}

.loader-bar {
  position: relative;
  height: 7px;
  margin: 20px 0 12px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
}

.loader-bar i {
  display: block;
  width: 0%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #4f9f37, #8fe76a);
  box-shadow: 0 0 16px rgba(126, 217, 87, 0.5);
  transition: width 0.25s ease;
}

.loader-text {
  color: #8fa39a;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
}

/* ---------------- HUD ---------------- */

#hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s;
}

#hud.is-active {
  opacity: 1;
  visibility: visible;
}

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 36px;
  height: 36px;
  margin: -18px 0 0 -18px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.85));
}

.ch-dot,
.ch-dot::before,
.ch-dot::after {
  position: absolute;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 1px;
}

.ch-dot {
  width: 4px;
  height: 4px;
}

.ch-dot::before,
.ch-dot::after {
  content: "";
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.ch-dot::before {
  width: 14px;
  height: 2px;
}

.ch-dot::after {
  width: 2px;
  height: 14px;
}

.ch-ring {
  position: absolute;
  inset: 0;
  width: 36px;
  height: 36px;
  transform: rotate(-90deg);
  opacity: 0;
  transition: opacity 0.1s;
}

.ch-ring circle {
  fill: none;
  stroke: var(--amber);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  filter: drop-shadow(0 0 4px rgba(255, 200, 87, 0.8));
}

#crosshair.is-mining .ch-ring {
  opacity: 1;
}

#crosshair.is-mining .ch-dot {
  background: var(--amber);
}

.hud-chip {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 9px;
  height: 30px;
  padding: 0 11px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  background: rgba(7, 13, 19, 0.52);
  color: #dce8f0;
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.02em;
  backdrop-filter: blur(10px);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
}

#hudTopLeft {
  left: calc(12px + var(--safe-l));
  top: calc(12px + var(--safe-t));
}

#hudTopRight {
  right: calc(12px + var(--safe-r));
  top: calc(12px + var(--safe-t));
  pointer-events: auto;
}

.hud-sep {
  width: 1px;
  height: 12px;
  background: rgba(255, 255, 255, 0.18);
}

#biomeText {
  color: var(--green);
}

.hud-icon-btn {
  display: none;
  width: 24px;
  height: 24px;
  margin-right: -5px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
  color: #dce8f0;
  cursor: pointer;
}

.hud-icon-btn svg {
  width: 14px;
  height: 14px;
  fill: currentColor;
}

#toast {
  position: absolute;
  left: 50%;
  bottom: calc(98px + var(--safe-b));
  transform: translate(-50%, 8px);
  padding: 8px 14px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 9px;
  background: rgba(8, 14, 20, 0.78);
  color: #f1f6fa;
  font-size: 12px;
  font-weight: 600;
