import * as THREE from 'three'
import { BLOCKS, isSolid } from './blocks.js'

const WIDTH = 0.6
const HALF = WIDTH / 2
const BODY_HEIGHT = 1.8
const EYE_HEIGHT = 1.62
const CROUCH_EYE = 1.32

const GRAVITY = 28
const JUMP_SPEED = 9.1

export class Player {
  constructor(camera, world) {
    this.camera = camera
    this.world = world
    this.pos = new THREE.Vector3(0, 40, 0)
    this.vel = new THREE.Vector3()
    this.yaw = -0.7
    this.pitch = -0.08
    this.onGround = false
    this.inWater = false
    this.flying = false
    this.sprinting = false
    this.crouching = false
    this.eyeHeight = EYE_HEIGHT
    this.bobPhase = 0
    this.bob = 0
    this.walkDistance = 0
    this.stepTimer = 0
    this.onStep = null
    this.onLand = null
    this.onSplash = null
    this.wasInWater = false
    this.input = { forward: 0, right: 0, jump: false, sprint: false, crouch: false }
    this.sensitivity = 1
    this.camera.rotation.order = 'YXZ'
  }

  setSpawn(spawn, yaw = -0.7) {
    this.pos.set(spawn.x, spawn.y, spawn.z)
    this.vel.set(0, 0, 0)
    this.yaw = yaw
    this.pitch = -0.08
    this.flying = false
    this.onGround = false
    this.updateCamera(0)
  }

  toggleFly() {
    this.flying = !this.flying
    this.vel.y = 0
    return this.flying
  }

  look(dx, dy) {
    const sens = 0.0022 * this.sensitivity
    this.yaw -= dx * sens
    this.pitch -= dy * sens
    const limit = Math.PI / 2 - 0.02
    this.pitch = Math.max(-limit, Math.min(limit, this.pitch))
  }

  collidesAt(x, y, z) {
    const minX = Math.floor(x - HALF + 0.0001)
    const maxX = Math.floor(x + HALF - 0.0001)
    const minY = Math.floor(y + 0.0001)
    const maxY = Math.floor(y + BODY_HEIGHT - 0.0001)
    const minZ = Math.floor(z - HALF + 0.0001)
    const maxZ = Math.floor(z + HALF - 0.0001)
    for (let by = minY; by <= maxY; by++) {
      for (let bz = minZ; bz <= maxZ; bz++) {
        for (let bx = minX; bx <= maxX; bx++) {
          if (isSolid(this.world.getBlock(bx, by, bz))) return true
        }
      }
    }
    return false
  }

  moveAxis(axis, amount) {
    if (amount === 0) return false
    this.pos[axis] += amount
    if (this.collidesAt(this.pos.x, this.pos.y, this.pos.z)) {
      this.pos[axis] -= amount
      if (axis === 'y') {
        if (amount < 0) {
          this.onGround = true
          if (this.vel.y < -9 && this.onLand) this.onLand(Math.abs(this.vel.y))
        }
        this.vel[axis] = 0
      }
      return true
    }
    return false
  }

  update(dt) {
    const input = this.input
    const wasOnGround = this.onGround
    this.onGround = false
    this.inWater = this.world.getBlock(Math.floor(this.pos.x), Math.floor(this.pos.y + 0.5), Math.floor(this.pos.z)) === 5
    const headWater = this.world.getBlock(Math.floor(this.pos.x), Math.floor(this.pos.y + EYE_HEIGHT), Math.floor(this.pos.z)) === 5
    this.headInWater = headWater
    if (this.inWater && !this.wasInWater && this.onSplash) this.onSplash()
    this.wasInWater = this.inWater

    const fwd = (input.forward || 0)
    const right = (input.right || 0)
    let wishX = -Math.sin(this.yaw) * fwd + Math.cos(this.yaw) * right
    let wishZ = -Math.cos(this.yaw) * fwd - Math.sin(this.yaw) * right
    const wishLen = Math.hypot(wishX, wishZ)
    if (wishLen > 1) {
      wishX /= wishLen
      wishZ /= wishLen
    }

    this.crouching = !!input.crouch && !this.flying
    this.sprinting = !!input.sprint && !this.crouching && wishLen > 0.1

    let speed = this.flying ? 12.5 : this.crouching ? 2.1 : this.sprinting ? 7.4 : 4.6
    if (this.inWater && !this.flying) speed *= 0.62

    const accel = this.flying ? 10 : this.onGround || wasOnGround ? 16 : 5
    const k = 1 - Math.exp(-accel * dt)
    const targetX = wishX * speed
    const targetZ = wishZ * speed
    this.vel.x += (targetX - this.vel.x) * k
    this.vel.z += (targetZ - this.vel.z) * k

    if (this.flying) {
      let targetY = 0
      if (input.jump) targetY += 1
      if (input.crouch) targetY -= 1
      this.vel.y += (targetY * 9 - this.vel.y) * (1 - Math.exp(-9 * dt))
    } else if (this.inWater) {
      this.vel.y -= 9 * dt
      if (input.jump) this.vel.y = Math.min(this.vel.y + 22 * dt, 4.2)
      this.vel.y = Math.max(this.vel.y, -4)
      this.vel.y *= 1 - Math.min(0.9, 2.2 * dt)
    } else {
      if (input.jump && (wasOnGround || this.onGround)) {
        this.vel.y = JUMP_SPEED
        this.onGround = false
      }
      this.vel.y -= GRAVITY * dt
      if (this.vel.y < -52) this.vel.y = -52
    }

    const dx = this.vel.x * dt
    const dz = this.vel.z * dt
    const dy = this.vel.y * dt

    this.moveAxis('x', dx)
    this.moveAxis('z', dz)
    const hitY = this.moveAxis('y', dy)

    // Ground probe keeps the player grounded while walking over small dips.
    if (!this.onGround && !this.flying && this.vel.y <= 0) {
      if (this.collidesAt(this.pos.x, this.pos.y - 0.08, this.pos.z)) {
        this.onGround = true
      }
    }

    if (this.pos.y < -8) {
      this.pos.y = 80
      this.vel.set(0, 0, 0)
    }

    const horizontalSpeed = Math.hypot(this.vel.x, this.vel.z)
    if (this.onGround && horizontalSpeed > 0.5) {
      this.walkDistance += horizontalSpeed * dt
      this.stepTimer += dt * horizontalSpeed
      const stepInterval = this.sprinting ? 1.9 : 2.5
      if (this.stepTimer > stepInterval) {
        this.stepTimer = 0
        if (this.onStep) this.onStep(this.inWater ? 'water' : 'grass')
      }
    }

    if (this.onGround && horizontalSpeed > 0.5) {
      this.bobPhase += dt * (this.sprinting ? 13 : 9.5)
      this.bob = Math.sin(this.bobPhase) * 0.035
    } else {
      this.bob *= Math.max(0, 1 - dt * 8)
    }

    const targetEye = this.crouching ? CROUCH_EYE : EYE_HEIGHT
    this.eyeHeight += (targetEye - this.eyeHeight) * Math.min(1, dt * 14)

    this.updateCamera(dt, horizontalSpeed)
    return { hitY, wasOnGround }
  }

  updateCamera(dt, horizontalSpeed = 0) {
    const bobY = this.bob * (this.flying ? 0 : 1)
    const sway = this.onGround ? Math.sin(this.bobPhase * 0.5) * 0.006 * Math.min(1, horizontalSpeed / 4) : 0
    this.camera.position.set(this.pos.x, this.pos.y + this.eyeHeight + bobY, this.pos.z)
    this.camera.rotation.set(this.pitch, this.yaw, sway, 'YXZ')
  }

  getEye(out = new THREE.Vector3()) {
    return out.set(this.pos.x, this.pos.y + this.eyeHeight + this.bob, this.pos.z)
  }

  getForward(out = new THREE.Vector3()) {
    const cp = Math.cos(this.pitch)
    return out.set(-Math.sin(this.yaw) * cp, Math.sin(this.pitch), -Math.cos(this.yaw) * cp).normalize()
  }

  raycast(maxDist = 6.5) {
    const origin = this.getEye()
    const dir = this.getForward()
    let x = Math.floor(origin.x)
    let y = Math.floor(origin.y)
    let z = Math.floor(origin.z)
    const stepX = dir.x > 0 ? 1 : dir.x < 0 ? -1 : 0
    const stepY = dir.y > 0 ? 1 : dir.y < 0 ? -1 : 0
    const stepZ = dir.z > 0 ? 1 : dir.z < 0 ? -1 : 0
    const tDeltaX = stepX === 0 ? Infinity : Math.abs(1 / dir.x)
    const tDeltaY = stepY === 0 ? Infinity : Math.abs(1 / dir.y)
    const tDeltaZ = stepZ === 0 ? Infinity : Math.abs(1 / dir.z)
    let tMaxX =
      stepX === 0 ? Infinity : stepX > 0 ? (x + 1 - origin.x) * tDeltaX : (origin.x - x) * tDeltaX
    let tMaxY =
      stepY === 0 ? Infinity : stepY > 0 ? (y + 1 - origin.y) * tDeltaY : (origin.y - y) * tDeltaY
    let tMaxZ =
      stepZ === 0 ? Infinity : stepZ > 0 ? (z + 1 - origin.z) * tDeltaZ : (origin.z - z) * tDeltaZ

    let normal = [0, 0, 0]
    let dist = 0
    for (let i = 0; i < 160; i++) {
      const id = this.world.getBlock(x, y, z)
      if (id !== 0 && id !== 5) {
        return { x, y, z, id, normal, dist, def: BLOCKS[id] }
      }
      if (tMaxX < tMaxY && tMaxX < tMaxZ) {
        if (tMaxX > maxDist) break
        x += stepX
        dist = tMaxX
        tMaxX += tDeltaX
        normal = [-stepX, 0, 0]
      } else if (tMaxY < tMaxZ) {
        if (tMaxY > maxDist) break
        y += stepY
        dist = tMaxY
        tMaxY += tDeltaY
        normal = [0, -stepY, 0]
      } else {
        if (tMaxZ > maxDist) break
        z += stepZ
        dist = tMaxZ
        tMaxZ += tDeltaZ
        normal = [0, 0, -stepZ]
      }
    }
    return null
  }

  blockIntersectsPlayer(bx, by, bz) {
    const minX = bx
    const maxX = bx + 1
    const minY = by
    const maxY = by + 1
    const minZ = bz
    const maxZ = bz + 1
    return (
      maxX > this.pos.x - HALF &&
      minX < this.pos.x + HALF &&
      maxY > this.pos.y &&
      minY < this.pos.y + BODY_HEIGHT &&
      maxZ > this.pos.z - HALF &&
      minZ < this.pos.z + HALF
    )
  }
}

import * as THREE from 'three'
import { smoothstep } from './noise.js'

const SKY_RADIUS = 430

function radialTexture(size, inner, outer, edgeAlpha = 0) {
  const canvas = document.createElement('canvas')
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, size * 0.05, size / 2, size / 2, size / 2)
  g.addColorStop(0, inner)
  g.addColorStop(0.45, outer)
  g.addColorStop(1, `rgba(255,255,255,${edgeAlpha})`)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function moonTexture() {
  const size = 128
  const canvas = document.createElement('canvas')
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext('2d')
  const g = ctx.createRadialGradient(size * 0.45, size * 0.42, 4, size / 2, size / 2, size * 0.48)
  g.addColorStop(0, 'rgba(244,248,255,1)')
  g.addColorStop(0.7, 'rgba(212,224,244,0.95)')
  g.addColorStop(1, 'rgba(180,200,230,0)')
  ctx.fillStyle = g
  ctx.beginPath()
  ctx.arc(size / 2, size / 2, size * 0.46, 0, Math.PI * 2)
  ctx.fill()
  const craters = [
    [0.38, 0.42, 0.07],
    [0.58, 0.36, 0.045],
    [0.53, 0.6, 0.08],
    [0.33, 0.62, 0.04],
    [0.64, 0.54, 0.035],
  ]
  ctx.fillStyle = 'rgba(156,172,200,0.35)'
  for (const [x, y, r] of craters) {
    ctx.beginPath()
    ctx.arc(size * x, size * y, size * r, 0, Math.PI * 2)
    ctx.fill()
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function cloudTexture() {
  const size = 256
  const canvas = document.createElement('canvas')
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, size, size)
  const blobs = [
    [0.28, 0.45, 0.16],
    [0.42, 0.36, 0.19],
    [0.58, 0.44, 0.17],
    [0.7, 0.5, 0.13],
    [0.4, 0.55, 0.14],
    [0.55, 0.58, 0.12],
    [0.24, 0.56, 0.1],
  ]
  for (const [x, y, r] of blobs) {
    const g = ctx.createRadialGradient(size * x, size * y, 0, size * x, size * y, size * r)
    g.addColorStop(0, 'rgba(255,255,255,0.85)')
    g.addColorStop(0.6, 'rgba(255,255,255,0.45)')
    g.addColorStop(1, 'rgba(255,255,255,0)')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, size, size)
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export class Sky {
  constructor(scene, sunLight, hemiLight, ambientLight) {
    this.scene = scene
    this.sunLight = sunLight
    this.hemiLight = hemiLight
    this.ambientLight = ambientLight

    this.uniforms = {
      topColor: { value: new THREE.Color('#4b9fe4') },
      bottomColor: { value: new THREE.Color('#cfe9ff') },
      horizonColor: { value: new THREE.Color('#e8f6ff') },
      sunDirection: { value: new THREE.Vector3(0.4, 0.8, 0.4) },
      sunColor: { value: new THREE.Color('#fff3c9') },
    }

    const skyMaterial = new THREE.ShaderMaterial({
      uniforms: this.uniforms,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      toneMapped: false,
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 topColor;
        uniform vec3 bottomColor;
        uniform vec3 horizonColor;
        uniform vec3 sunDirection;
        uniform vec3 sunColor;
        varying vec3 vDir;
        void main() {
          vec3 dir = normalize(vDir);
          float h = clamp(dir.y, -1.0, 1.0);
          float t = pow(clamp(h, 0.0, 1.0), 0.55);
          vec3 col = mix(bottomColor, topColor, t);
          float horizon = pow(1.0 - abs(h), 9.0);
          col = mix(col, horizonColor, horizon * 0.78);
          float sunDot = max(dot(dir, normalize(sunDirection)), 0.0);
          col += sunColor * pow(sunDot, 700.0) * 2.6;
          col += sunColor * pow(sunDot, 16.0) * 0.14;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    })

    this.sky = new THREE.Mesh(new THREE.SphereGeometry(SKY_RADIUS, 32, 20), skyMaterial)
    this.sky.frustumCulled = false
    this.sky.renderOrder = -100
    scene.add(this.sky)

    const sunTex = radialTexture(128, 'rgba(255,255,244,1)', 'rgba(255,226,140,0.9)', 0)
    this.sun = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: sunTex,
        transparent: true,
        depthWrite: false,
        depthTest: true,
        blending: THREE.AdditiveBlending,
        toneMapped: false,
        fog: false,
      }),
    )
    this.sun.scale.set(46, 46, 1)
    scene.add(this.sun)

    this.moon = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: moonTexture(),
        transparent: true,
        depthWrite: false,
        depthTest: true,
        toneMapped: false,
        fog: false,
      }),
    )
    this.moon.scale.set(26, 26, 1)
    scene.add(this.moon)

    const starCount = 900
    const positions = new Float32Array(starCount * 3)
    for (let i = 0; i < starCount; i++) {
      const theta = Math.random() * Math.PI * 2
      const phi = Math.acos(1 - Math.random() * 1.35)
      const r = 390
      positions[i * 3] = Math.sin(phi) * Math.cos(theta) * r
      positions[i * 3 + 1] = Math.cos(phi) * r
      positions[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * r
    }
    const starGeo = new THREE.BufferGeometry()
    starGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    this.starMaterial = new THREE.PointsMaterial({
      color: 0xdfe9ff,
      size: 1.5,
      sizeAttenuation: false,
      transparent: true,
      opacity: 0,
      depthWrite: false,
      fog: false,
      toneMapped: false,
    })
    this.stars = new THREE.Points(starGeo, this.starMaterial)
    this.stars.frustumCulled = false
    scene.add(this.stars)

    this.cloudGroup = new THREE.Group()
    const cloudTex = cloudTexture()
    this.clouds = []
    const cloudGeo = new THREE.PlaneGeometry(1, 1)
    for (let i = 0; i < 30; i++) {
      const mat = new THREE.MeshBasicMaterial({
        map: cloudTex,
        transparent: true,
        opacity: 0.5,
        depthWrite: false,
        fog: false,
        side: THREE.DoubleSide,
        toneMapped: false,
      })
      const mesh = new THREE.Mesh(cloudGeo, mat)
      const scale = 26 + Math.random() * 42
      mesh.scale.set(scale, scale, 1)
      mesh.rotation.x = -Math.PI / 2
      mesh.rotation.z = Math.random() * Math.PI * 2
      mesh.position.set((Math.random() - 0.5) * 320, 82 + Math.random() * 18, (Math.random() - 0.5) * 320)
      mesh.userData.baseX = mesh.position.x
      mesh.userData.baseZ = mesh.position.z
      mesh.userData.drift = Math.random() * 320
      mesh.renderOrder = -50
      this.cloudGroup.add(mesh)
      this.clouds.push(mesh)
    }
    scene.add(this.cloudGroup)

    this.fogColor = new THREE.Color('#cfe9ff')
    this.dayFactor = 1
    this.sunDir = new THREE.Vector3(0.4, 0.8, 0.4)
    this._dayTop = new THREE.Color('#4b9fe4')
    this._dayBottom = new THREE.Color('#cfe9ff')
    this._dayHorizon = new THREE.Color('#e8f6ff')
    this._duskTop = new THREE.Color('#24345f')
    this._duskBottom = new THREE.Color('#ff9d5c')
    this._duskHorizon = new THREE.Color('#ffd79a')
    this._nightTop = new THREE.Color('#050a18')
    this._nightBottom = new THREE.Color('#101c36')
    this._nightHorizon = new THREE.Color('#1d2c50')
    this._tmp = new THREE.Color()
    this._tmp2 = new THREE.Color()
  }

  update(dt, dayTime, camera) {
    const angle = (dayTime - 0.25) * Math.PI * 2
    const elevation = Math.sin(angle)
    const sunDir = this.sunDir.set(Math.cos(angle) * 0.72, Math.sin(angle), 0.5).normalize()
    const dayFactor = smoothstep(-0.12, 0.2, elevation)
    const sunset = Math.exp(-Math.pow(elevation / 0.24, 2))
    this.dayFactor = dayFactor

    const top = this._tmp.copy(this._nightTop).lerp(this._dayTop, dayFactor)
    top.lerp(this._duskTop, sunset * 0.62)
    const bottom = this._tmp2.copy(this._nightBottom).lerp(this._dayBottom, dayFactor)
    bottom.lerp(this._duskBottom, sunset * 0.7)
    const horizon = new THREE.Color().copy(this._nightHorizon).lerp(this._dayHorizon, dayFactor)
    horizon.lerp(this._duskHorizon, sunset * 0.8)

    this.uniforms.topColor.value.copy(top)
    this.uniforms.bottomColor.value.copy(bottom)
    this.uniforms.horizonColor.value.copy(horizon)
    this.uniforms.sunDirection.value.copy(sunDir)
    this.uniforms.sunColor.value.setRGB(
      1,
      0.9 + sunset * 0.08,
      0.72 + dayFactor * 0.2,
    )

    this.fogColor.copy(bottom).lerp(horizon, 0.62)

    this.sky.position.copy(camera.position)
    this.stars.position.copy(camera.position)
    this.cloudGroup.position.set(camera.position.x, 0, camera.position.z)

    this.sun.position.copy(camera.position).addScaledVector(sunDir, 300)
    this.moon.position.copy(camera.position).addScaledVector(sunDir, -300)
    this.sun.material.opacity = Math.max(0, smoothstep(-0.08, 0.12, elevation))
    this.moon.material.opacity = Math.max(0, smoothstep(-0.05, 0.15, -elevation)) * 0.95
    this.starMaterial.opacity = Math.max(0, 1 - dayFactor) * 0.9

    const lightDir = elevation >= 0 ? sunDir : sunDir.clone().negate()
    this.sunLight.position.copy(camera.position).addScaledVector(lightDir, 120)
    this.sunLight.target.position.copy(camera.position)
    this.sunLight.target.updateMatrixWorld()
    this.sunLight.intensity = 0.18 + dayFactor * 1.28
    if (dayFactor < 0.25) {
      this.sunLight.color.set('#a9c7ff')
    } else if (sunset > 0.35) {
      this.sunLight.color.set('#ffc08a')
    } else {
      this.sunLight.color.set('#fff1cf')
    }

    this.hemiLight.intensity = 0.22 + dayFactor * 0.82
    this.hemiLight.color.set(dayFactor > 0.4 ? '#c3e7ff' : '#7f9bd0')
    this.hemiLight.groundColor.set(dayFactor > 0.4 ? '#5d4a32' : '#151b2b')
    this.ambientLight.intensity = 0.08 + dayFactor * 0.1

    const cloudTint = this._tmp.copy(new THREE.Color('#ffffff')).lerp(new THREE.Color('#7f8eae'), 1 - dayFactor)
    for (const cloud of this.clouds) {
      cloud.material.opacity = 0.16 + dayFactor * 0.5
      cloud.material.color.copy(cloudTint)
      cloud.userData.drift += dt * 0.55
      const drift = cloud.userData.drift
      cloud.position.x = ((cloud.userData.baseX + drift + 160) % 320) - 160
      cloud.position.z = cloud.userData.baseZ
    }
  }
}

export class Sound {
  constructor() {
    this.ctx = null
    this.master = null
    this.enabled = true
    this.noiseBuffer = null
    this.ambientTimer = 5 + Math.random() * 8
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    try {
      this.ctx = new Ctx()
      this.master = this.ctx.createGain()
      this.master.gain.value = 0.55
      this.master.connect(this.ctx.destination)
      const length = Math.floor(this.ctx.sampleRate * 1.2)
      const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
      const data = buffer.getChannelData(0)
      for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
      this.noiseBuffer = buffer
    } catch {
      this.ctx = null
    }
  }

  setEnabled(value) {
    this.enabled = value
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(value ? 0.55 : 0, this.ctx.currentTime, 0.05)
    }
  }

  noise(duration, frequency, gain, type = 'lowpass', q = 0.8) {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.loop = true
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.value = frequency
    filter.Q.value = q
    const env = this.ctx.createGain()
    env.gain.setValueAtTime(0.0001, now)
    env.gain.exponentialRampToValueAtTime(gain, now + 0.008)
    env.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    src.connect(filter).connect(env).connect(this.master)
    src.start(now)
    src.stop(now + duration + 0.02)
  }

  tone(freq, duration, gain, type = 'sine', endFreq = null) {
    if (!this.ctx || !this.enabled) return
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    osc.type = type
    osc.frequency.setValueAtTime(freq, now)
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), now + duration)
    const env = this.ctx.createGain()
    env.gain.setValueAtTime(0.0001, now)
    env.gain.exponentialRampToValueAtTime(gain, now + 0.01)
    env.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    osc.connect(env).connect(this.master)
    osc.start(now)
    osc.stop(now + duration + 0.02)
  }

  step(kind = 'grass') {
    if (!this.ctx || !this.enabled) return
    const freq = kind === 'water' ? 950 : 380 + Math.random() * 220
    this.noise(0.07, freq, 0.035, 'lowpass')
  }

  breakBlock(id) {
    const hard = id === 3 || id === 10 || id === 12 || id === 21 ? 1 : 0
    this.noise(0.16, hard ? 520 : 900, 0.1, 'bandpass', 1.2)
    this.tone(hard ? 92 : 140, 0.09, 0.05, 'triangle', 58)
  }

  place() {
    this.noise(0.05, 1400, 0.04, 'bandpass', 1.4)
    this.tone(220, 0.06, 0.04, 'square', 150)
  }

  jump() {
    this.tone(210, 0.09, 0.025, 'sine', 320)
  }

  land(intensity) {
    this.noise(0.1, 300, Math.min(0.09, 0.02 + intensity * 0.006), 'lowpass')
  }

  splash() {
    this.noise(0.3, 1200, 0.06, 'lowpass')
  }

  toggleFly(on) {
    this.tone(on ? 420 : 300, 0.14, 0.03, 'sine', on ? 640 : 210)
  }

  update(dt, dayFactor) {
    if (!this.ctx || !this.enabled) return
    this.ambientTimer -= dt
    if (this.ambientTimer <= 0) {
      this.ambientTimer = 7 + Math.random() * 13
      if (dayFactor > 0.45 && Math.random() < 0.7) {
        const base = 1700 + Math.random() * 900
        this.tone(base, 0.11, 0.012, 'sine', base * 1.5)
        window.setTimeout(() => this.tone(base * 1.18, 0.09, 0.009, 'sine', base * 1.45), 130)
      }
    }
  }
}

import * as THREE from 'three'
import { BLOCKS } from './blocks.js'

const box = new THREE.BoxGeometry(1, 1, 1)

function material(color) {
  return new THREE.MeshLambertMaterial({ color })
}

const MAT = {
  pig: material('#e79a9a'),
  pigSnout: material('#c97777'),
  pigEye: material('#241a1a'),
  sheep: material('#ecebe2'),
  sheepFace: material('#d8c6ac'),
  sheepLeg: material('#c9b89e'),
  sheepEye: material('#2a2320'),
  chicken: material('#f3efe4'),
  chickenBeak: material('#e8a83c'),
  chickenComb: material('#c94b45'),
  chickenLeg: material('#d99b45'),
}

function part(parent, mat, x, y, z, sx, sy, sz) {
  const mesh = new THREE.Mesh(box, mat)
  mesh.position.set(x, y, z)
  mesh.scale.set(sx, sy, sz)
  parent.add(mesh)
  return mesh
}

export class Mob {
  constructor(scene, world, type, x, z) {
    this.scene = scene
    this.world = world
    this.type = type
    this.group = new THREE.Group()
    this.home = new THREE.Vector2(x, z)
    this.speed = 0
    this.turn = 0
    this.wander = 2 + Math.random() * 5
    this.phase = Math.random() * Math.PI * 2
    this.yaw = Math.random() * Math.PI * 2
    this.legs = []
    this.build()
    const y = world.surfaceY(Math.floor(x), Math.floor(z))
    this.group.position.set(x, y, z)
    this.group.rotation.y = this.yaw
    scene.add(this.group)
  }

  build() {
    const g = this.group
    if (this.type === 'pig') {
      part(g, MAT.pig, 0, 0.72, 0, 0.95, 0.72, 1.35)
      const head = new THREE.Group()
      head.position.set(0, 0.88, 0.78)
      part(head, MAT.pig, 0, 0, 0, 0.68, 0.64, 0.6)
      part(head, MAT.pigSnout, 0, -0.08, 0.34, 0.38, 0.28, 0.16)
      part(head, MAT.pigEye, -0.18, 0.12, 0.29, 0.09, 0.09, 0.04)
      part(head, MAT.pigEye, 0.18, 0.12, 0.29, 0.09, 0.09, 0.04)
      part(head, MAT.pig, -0.25, 0.34, -0.02, 0.2, 0.2, 0.1)
      part(head, MAT.pig, 0.25, 0.34, -0.02, 0.2, 0.2, 0.1)
      g.add(head)
      this.head = head
      const legPositions = [
        [-0.32, 0.38],
        [0.32, 0.38],
        [-0.32, -0.38],
        [0.32, -0.38],
      ]
      for (const [lx, lz] of legPositions) {
        const pivot = new THREE.Group()
        pivot.position.set(lx, 0.38, lz)
        part(pivot, MAT.pigSnout, 0, -0.19, 0, 0.24, 0.38, 0.24)
        g.add(pivot)
        this.legs.push(pivot)
      }
    } else if (this.type === 'sheep') {
      part(g, MAT.sheep, 0, 0.78, 0, 1.08, 0.88, 1.32)
      part(g, MAT.sheep, 0, 1.14, -0.05, 0.92, 0.36, 1.08)
      const head = new THREE.Group()
      head.position.set(0, 0.94, 0.82)
      part(head, MAT.sheepFace, 0, 0, 0.05, 0.56, 0.62, 0.56)
      part(head, MAT.sheep, 0, 0.18, -0.02, 0.62, 0.34, 0.62)
      part(head, MAT.sheepEye, -0.16, 0.08, 0.33, 0.08, 0.1, 0.04)
      part(head, MAT.sheepEye, 0.16, 0.08, 0.33, 0.08, 0.1, 0.04)
      g.add(head)
      this.head = head
      const legPositions = [
        [-0.34, 0.4],
        [0.34, 0.4],
        [-0.34, -0.4],
        [0.34, -0.4],
      ]
      for (const [lx, lz] of legPositions) {
        const pivot = new THREE.Group()
        pivot.position.set(lx, 0.4, lz)
        part(pivot, MAT.sheepLeg, 0, -0.2, 0, 0.22, 0.4, 0.22)
        g.add(pivot)
        this.legs.push(pivot)
      }
    } else {
      part(g, MAT.chicken, 0, 0.52, 0, 0.58, 0.56, 0.78)
      const head = new THREE.Group()
      head.position.set(0, 0.92, 0.28)
      part(head, MAT.chicken, 0, 0, 0, 0.36, 0.38, 0.36)
      part(head, MAT.chickenBeak, 0, -0.02, 0.22, 0.16, 0.12, 0.2)
      part(head, MAT.chickenComb, 0, 0.24, 0, 0.1, 0.16, 0.2)
      part(head, MAT.pigEye, -0.11, 0.07, 0.17, 0.06, 0.07, 0.03)
      part(head, MAT.pigEye, 0.11, 0.07, 0.17, 0.06, 0.07, 0.03)
      g.add(head)
      this.head = head
      const legPositions = [
        [-0.17, 0.18],
        [0.17, 0.18],
        [-0.17, -0.2],
        [0.17, -0.2],
      ]
      for (const [lx, lz] of legPositions) {
        const pivot = new THREE.Group()
        pivot.position.set(lx, 0.3, lz)
        part(pivot, MAT.chickenLeg, 0, -0.15, 0, 0.1, 0.3, 0.1)
        g.add(pivot)
        this.legs.push(pivot)
      }
    }
  }

  update(dt, playerPos) {
    this.wander -= dt
    if (this.wander <= 0) {
      this.wander = 2.5 + Math.random() * 6
      if (Math.random() < 0.35) {
        this.speed = 0
      } else {
        this.speed = this.type === 'chicken' ? 1.6 : 1.05
        this.yaw = Math.random() * Math.PI * 2
      }
    }

    const px = this.group.position.x
    const pz = this.group.position.z
    const homeDist = Math.hypot(px - this.home.x, pz - this.home.y)
    if (homeDist > 26) {
      this.yaw = Math.atan2(this.home.x - px, this.home.y - pz)
      this.speed = 1.2
    }

    if (this.speed > 0) {
      const dx = Math.sin(this.yaw) * this.speed * dt
      const dz = Math.cos(this.yaw) * this.speed * dt
      const nextX = px + dx
      const nextZ = pz + dz
      const ground = this.world.surfaceY(Math.floor(nextX), Math.floor(nextZ))
      const ahead = this.world.getBlock(Math.floor(nextX), ground - 1, Math.floor(nextZ))
      const blockAhead = BLOCKS[ahead]
      const blocked = !blockAhead || ahead === 5 || ahead === 7 || Math.abs(ground - this.group.position.y) > 1.1
      if (!blocked) {
        this.group.position.x = nextX
        this.group.position.z = nextZ
        this.group.position.y += (ground - this.group.position.y) * Math.min(1, dt * 8)
      } else {
        this.yaw += Math.PI * (0.45 + Math.random() * 0.4)
        this.speed *= 0.4
      }
    }

    const targetRot = this.yaw
    let diff = targetRot - this.group.rotation.y
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    this.group.rotation.y += diff * Math.min(1, dt * 6)

    const moving = this.speed > 0.05
    this.phase += dt * (moving ? 8.5 : 2.2)
    const swing = moving ? Math.sin(this.phase) * 0.55 : Math.sin(this.phase) * 0.06
    this.legs[0].rotation.x = swing
    this.legs[1].rotation.x = -swing
    this.legs[2].rotation.x = -swing
    this.legs[3].rotation.x = swing
    if (this.head) {
      this.head.rotation.x = moving ? Math.sin(this.phase * 2) * 0.04 : Math.sin(this.phase) * 0.03
    }

    if (playerPos && this.group.position.distanceToSquared(playerPos) > 120 * 120) {
      this.group.visible = false
    } else {
      this.group.visible = true
    }
  }
}

export class Mobs {
  constructor(scene, world) {
    this.scene = scene
    this.world = world
    this.mobs = []
  }

  spawn(count, center) {
    const types = ['pig', 'sheep', 'chicken', 'sheep', 'pig', 'chicken', 'sheep', 'pig', 'chicken', 'sheep']
    for (let i = 0; i < count; i++) {
      let placed = false
      for (let attempt = 0; attempt < 24 && !placed; attempt++) {
        const angle = Math.random() * Math.PI * 2
        const radius = 7 + Math.random() * 22
        const x = center.x + Math.cos(angle) * radius
        const z = center.z + Math.sin(angle) * radius
        const ground = this.world.surfaceY(Math.floor(x), Math.floor(z))
        const below = this.world.getBlock(Math.floor(x), ground - 1, Math.floor(z))
        if (below === 1 || below === 2 || below === 4 || below === 8) {
          if (ground > 5) {
            this.mobs.push(new Mob(this.scene, this.world, types[i % types.length], x, z))
            placed = true
          }
        }
      }
    }
  }

  update(dt, playerPos) {
    for (const mob of this.mobs) mob.update(dt, playerPos)
  }
}

