input.newString:
findOpenSpot(sx, sz) {
  let best = { x: sx, z: sz, score: Infinity }
  for (let dz = -10; dz <= 10; dz += 2) {
    for (let dx = -10; dx <= 10; dx += 2) {
      const x = sx + dx
      const z = sz + dz
      const h = this.heightAt(x, z)
      if (h <= SEA_LEVEL + 2 || h > 48) continue
      let score = Math.hypot(dx, dz) * 0.12
      for (let oz = -3; oz <= 3; oz++) {
        for (let ox = -3; ox <= 3; ox++) {
          for (let y = h + 1; y <= h + 8; y++) {
            const id = this.getBlock(x + ox, y, z + oz)
            if (id === 6 || id === 7) score += 1
          }
        }
      }
      if (score < best.score) best = { x, z, score }
    }
  }
  return best
}

prepareSpawn(sx, sz) {
  const spot = this.findOpenSpot(sx, sz)
  sx = spot.x
  sz = spot.z
  const h0 = this.heightAt(sx, sz)
  for (let dz = -6; dz <= 6; dz++) {
    for (let dx = -6; dx <= 6; dx++) {
      const x = sx + dx
      const z = sz + dz
      const h = this.heightAt(x, z)
      for (let y = h + 1; y <= Math.min(HEIGHT - 1, h + 14); y++) {
        this.setBlock(x, y, z, 0, false)
      }
      const top = this.getBlock(x, h, z)
      if (top === 6 || top === 7) this.setBlock(x, h, z, 0, false)
      if (Math.abs(dx) <= 2 && Math.abs(dz) <= 2) {
        for (let y = h + 1; y <= h0 + 6; y++) this.setBlock(x, y, z, 0, false)
        for (let y = h + 1; y < h0; y++) this.setBlock(x, y, z, 2, false)
        this.setBlock(x, h0, z, 1, false)
      }
    }
  }
  return { x: sx + 0.5, y: h0 + 1, z: sz + 0.5 }
}

