import * as THREE from 'three'
import { BLOCKS, isSolid } from './blocks.js'

const WIDTH = 0.6
const HALF = WIDTH / 2
const BODY_HEIGHT = 1.8
const EYE_HEIGHT = 1.62
const CROUCH_EYE = 1.32

const GRAVITY = 28
const JUMP_SPEED = 9.1

export class Player {
  constructor(camera, world) {
    this.camera = camera
    this.world = world
    this.pos = new THREE.Vector3(0, 40, 0)
    this.vel = new THREE.Vector3()
    this.yaw = -0.7
    this.pitch = -0.08
    this.onGround = false
    this.inWater = false
    this.flying = false
    this.sprinting = false
    this.crouching = false
    this.eyeHeight = EYE_HEIGHT
    this.bobPhase = 0
    this.bob = 0
    this.walkDistance = 0
    this.stepTimer = 0
    this.onStep = null
    this.onLand = null
    this.onSplash = null
    this.wasInWater = false
    this.input = { forward: 0, right: 0, jump: false, sprint: false, crouch: false }
    this.sensitivity = 1
    this.camera.rotation.order = 'YXZ'
  }

  setSpawn(spawn, yaw = -0.7) {
    this.pos.set(spawn.x, spawn.y, spawn.z)
    this.vel.set(0, 0, 0)
    this.yaw = yaw
    this.pitch = -0.08
    this.flying = false
    this.onGround = false
    this.updateCamera(0)
  }

  toggleFly() {
    this.flying = !this.flying
    this.vel.y = 0
    return this.flying
  }

  look(dx, dy) {
    const sens = 0.0022 * this.sensitivity
    this.yaw -= dx * sens
    this.pitch -= dy * sens
    const limit = Math.PI / 2 - 0.02
    this.pitch = Math.max(-limit, Math.min(limit, this.pitch))
  }

  collidesAt(x, y, z) {
    const minX = Math.floor(x - HALF + 0.0001)
    const maxX = Math.floor(x + HALF - 0.0001)
    const minY = Math.floor(y + 0.0001)
    const maxY = Math.floor(y + BODY_HEIGHT - 0.0001)
    const minZ = Math.floor(z - HALF + 0.0001)
    const maxZ = Math.floor(z + HALF - 0.0001)
    for (let by = minY; by <= maxY; by++) {
      for (let bz = minZ; bz <= maxZ; bz++) {
        for (let bx = minX; bx <= maxX; bx++) {
          if (isSolid(this.world.getBlock(bx, by, bz))) return true
        }
      }
    }
    return false
  }

  moveAxis(axis, amount) {
    if (amount === 0) return false
    this.pos[axis] += amount
    if (this.collidesAt(this.pos.x, this.pos.y, this.pos.z)) {
      this.pos[axis] -= amount
      if (axis === 'y') {
        if (amount < 0) {
          this.onGround = true
          if (this.vel.y < -9 && this.onLand) this.onLand(Math.abs(this.vel.y))
        }
        this.vel[axis] = 0
      }
      return true
    }
    return false
  }

  update(dt) {
    const input = this.input
    const wasOnGround = this.onGround
    this.onGround = false
    this.inWater = this.world.getBlock(Math.floor(this.pos.x), Math.floor(this.pos.y + 0.5), Math.floor(this.pos.z)) === 5
    const headWater = this.world.getBlock(Math.floor(this.pos.x), Math.floor(this.pos.y + EYE_HEIGHT), Math.floor(this.pos.z)) === 5
    this.headInWater = headWater
    if (this.inWater && !this.wasInWater && this.onSplash) this.onSplash()
    this.wasInWater = this.inWater

    const fwd = (input.forward || 0)
    const right = (input.right || 0)
    let wishX = -Math.sin(this.yaw) * fwd + Math.cos(this.yaw) * right
    let wishZ = -Math.cos(this.yaw) * fwd - Math.sin(this.yaw) * right
    const wishLen = Math.hypot(wishX, wishZ)
    if (wishLen > 1) {
      wishX /= wishLen
      wishZ /= wishLen
    }

    this.crouching = !!input.crouch && !this.flying
    this.sprinting = !!input.sprint && !this.crouching && wishLen > 0.1

    let speed = this.flying ? 12.5 : this.crouching ? 2.1 : this.sprinting ? 7.4 : 4.6
    if (this.inWater && !this.flying) speed *= 0.62

    const accel = this.flying ? 10 : this.onGround || wasOnGround ? 16 : 5
    const k = 1 - Math.exp(-accel * dt)
    const targetX = wishX * speed
    const targetZ = wishZ * speed
    this.vel.x += (targetX - this.vel.x) * k
    this.vel.z += (targetZ - this.vel.z) * k

    if (this.flying) {
      let targetY = 0
      if (input.jump) targetY += 1
      if (input.crouch) targetY -= 1
      this.vel.y += (targetY * 9 - this.vel.y) * (1 - Math.exp(-9 * dt))
    } else if (this.inWater) {
      this.vel.y -= 9 * dt
      if (input.jump) this.vel.y = Math.min(this.vel.y + 22 * dt, 4.2)
      this.vel.y = Math.max(this.vel.y, -4)
      this.vel.y *= 1 - Math.min(0.9, 2.2 * dt)
    } else {
      if (input.jump && (wasOnGround || this.onGround)) {
        this.vel.y = JUMP_SPEED
        this.onGround = false
      }
      this.vel.y -= GRAVITY * dt
      if (this.vel.y < -52) this.vel.y = -52
    }

    const dx = this.vel.x * dt
    const dz = this.vel.z * dt
    const dy = this.vel.y * dt

    this.moveAxis('x', dx)
    this.moveAxis('z', dz)
    const hitY = this.moveAxis('y', dy)

    // Ground probe keeps the player grounded while walking over small dips.
    if (!this.onGround && !this.flying && this.vel.y <= 0) {
      if (this.collidesAt(this.pos.x, this.pos.y - 0.08, this.pos.z)) {
        this.onGround = true
      }
    }

    if (this.pos.y < -8) {
      this.pos.y = 80
      this.vel.set(0, 0, 0)
    }

    const horizontalSpeed = Math.hypot(this.vel.x, this.vel.z)
    if (this.onGround && horizontalSpeed > 0.5) {
      this.walkDistance += horizontalSpeed * dt
      this.stepTimer += dt * horizontalSpeed
      const stepInterval = this.sprinting ? 1.9 : 2.5
      if (this.stepTimer > stepInterval) {
        this.stepTimer = 0
        if (this.onStep) this.onStep(this.inWater ? 'water' : 'grass')
      }
    }

    if (this.onGround && horizontalSpeed > 0.5) {
      this.bobPhase += dt * (this.sprinting ? 13 : 9.5)
      this.bob = Math.sin(this.bobPhase) * 0.035
    } else {
      this.bob *= Math.max(0, 1 - dt * 8)
    }

    const targetEye = this.crouching ? CROUCH_EYE : EYE_HEIGHT
    this.eyeHeight += (targetEye - this.eyeHeight) * Math.min(1, dt * 14)

    this.updateCamera(dt, horizontalSpeed)
    return { hitY, wasOnGround }
  }

  updateCamera(dt, horizontalSpeed = 0) {
    const bobY = this.bob * (this.flying ? 0 : 1)
    const sway = this.onGround ? Math.sin(this.bobPhase * 0.5) * 0.006 * Math.min(1, horizontalSpeed / 4) : 0
    this.camera.position.set(this.pos.x, this.pos.y + this.eyeHeight + bobY, this.pos.z)
    this.camera.rotation.set(this.pitch, this.yaw, sway, 'YXZ')
  }

  getEye(out = new THREE.Vector3()) {
    return out.set(this.pos.x, this.pos.y + this.eyeHeight + this.bob, this.pos.z)
  }

  getForward(out = new THREE.Vector3()) {
    const cp = Math.cos(this.pitch)
    return out.set(-Math.sin(this.yaw) * cp, Math.sin(this.pitch), -Math.cos(this.yaw) * cp).normalize()
  }

  raycast(maxDist = 6.5) {
    const origin = this.getEye()
    const dir = this.getForward()
    let x = Math.floor(origin.x)
    let y = Math.floor(origin.y)
    let z = Math.floor(origin.z)
    const stepX = dir.x > 0 ? 1 : dir.x < 0 ? -1 : 0
    const stepY = dir.y > 0 ? 1 : dir.y < 0 ? -1 : 0
    const stepZ = dir.z > 0 ? 1 : dir.z < 0 ? -1 : 0
    const tDeltaX = stepX === 0 ? Infinity : Math.abs(1 / dir.x)
    const tDeltaY = stepY === 0 ? Infinity : Math.abs(1 / dir.y)
    const tDeltaZ = stepZ === 0 ? Infinity : Math.abs(1 / dir.z)
    let tMaxX =
      stepX === 0 ? Infinity : stepX > 0 ? (x + 1 - origin.x) * tDeltaX : (origin.x - x) * tDeltaX
    let tMaxY =
      stepY === 0 ? Infinity : stepY > 0 ? (y + 1 - origin.y) * tDeltaY : (origin.y - y) * tDeltaY
    let tMaxZ =
      stepZ === 0 ? Infinity : stepZ > 0 ? (z + 1 - origin.z) * tDeltaZ : (origin.z - z) * tDeltaZ

    let normal = [0, 0, 0]
    let dist = 0
    for (let i = 0; i < 160; i++) {
      const id = this.world.getBlock(x, y, z)
      if (id !== 0 && id !== 5) {
        return { x, y, z, id, normal, dist, def: BLOCKS[id] }
      }
      if (tMaxX < tMaxY && tMaxX < tMaxZ) {
        if (tMaxX > maxDist) break
        x += stepX
        dist = tMaxX
        tMaxX += tDeltaX
        normal = [-stepX, 0, 0]
      } else if (tMaxY < tMaxZ) {
        if (tMaxY > maxDist) break
        y += stepY
        dist = tMaxY
        tMaxY += tDeltaY
        normal = [0, -stepY, 0]
      } else {
        if (tMaxZ > maxDist) break
        z += stepZ
        dist = tMaxZ
        tMaxZ += tDeltaZ
        normal = [0, 0, -stepZ]
      }
    }
    return null
  }

  blockIntersectsPlayer(bx, by, bz) {
    const minX = bx
    const maxX = bx + 1
    const minY = by
    const maxY = by + 1
    const minZ = bz
    const maxZ = bz + 1
    return (
      maxX > this.pos.x - HALF &&
      minX < this.pos.x + HALF &&
      maxY > this.pos.y &&
      minY < this.pos.y + BODY_HEIGHT &&
      maxZ > this.pos.z - HALF &&
      minZ < this.pos.z + HALF
    )
  }
}

import * as THREE from 'three'
import { mulberry32 } from './noise.js'

export const ATLAS_COLS = 8
export const TILE = 16
export const ATLAS_PX = ATLAS_COLS * TILE

const T = {
  grassTop: 0,
  grassSide: 1,
  dirt: 2,
  stone: 3,
  sand: 4,
  snow: 5,
  logSide: 6,
  logTop: 7,
  leaves: 8,
  planks: 9,
  cobble: 10,
  glass: 11,
  brick: 12,
  gravel: 13,
  coal: 14,
  iron: 15,
  bedrock: 16,
  water: 17,
  sandstone: 18,
  flower: 19,
  tallgrass: 20,
  glowstone: 21,
  obsidian: 22,
  ice: 23,
  pumpkinSide: 24,
  pumpkinTop: 25,
  pumpkinFace: 26,
  cactusSide: 27,
  cactusTop: 28,
  woolWhite: 29,
  woolRed: 30,
  clay: 31,
  mossyCobble: 32,
}

function clampByte(v) {
  return v < 0 ? 0 : v > 255 ? 255 : v | 0
}

function shade(rgb, amount) {
  return [clampByte(rgb[0] + amount), clampByte(rgb[1] + amount), clampByte(rgb[2] + amount)]
}

function rgba(rgb, alpha = 1) {
  return `rgba(${clampByte(rgb[0])},${clampByte(rgb[1])},${clampByte(rgb[2])},${alpha})`
}

function tileOrigin(t) {
  return { x: (t % ATLAS_COLS) * TILE, y: Math.floor(t / ATLAS_COLS) * TILE }
}

function paintBase(ctx, t, base, spread, seed) {
  const { x: ox, y: oy } = tileOrigin(t)
  const rand = mulberry32(seed)
  for (let y = 0; y < TILE; y++) {
    for (let x = 0; x < TILE; x++) {
      const n = (rand() - 0.5) * spread * 2
      ctx.fillStyle = rgba(shade(base, n))
      ctx.fillRect(ox + x, oy + y, 1, 1)
    }
  }
}

function pixel(ctx, t, x, y, rgb, alpha = 1) {
  if (x < 0 || y < 0 || x >= TILE || y >= TILE) return
  const { x: ox, y: oy } = tileOrigin(t)
  ctx.fillStyle = rgba(rgb, alpha)
  ctx.fillRect(ox + x, oy + y, 1, 1)
}

function rect(ctx, t, x, y, w, h, rgb, alpha = 1) {
  const { x: ox, y: oy } = tileOrigin(t)
  ctx.fillStyle = rgba(rgb, alpha)
  ctx.fillRect(ox + x, oy + y, w, h)
}

function speckles(ctx, t, count, seed, colors, minSize = 1, maxSize = 2) {
  const rand = mulberry32(seed)
  for (let i = 0; i < count; i++) {
    const x = Math.floor(rand() * TILE)
    const y = Math.floor(rand() * TILE)
    const w = minSize + Math.floor(rand() * (maxSize - minSize + 1))
    const h = minSize + Math.floor(rand() * (maxSize - minSize + 1))
    rect(ctx, t, x, y, w, h, colors[Math.floor(rand() * colors.length)])
  }
}

function drawTiles(ctx) {
  // 0 — grass top
  paintBase(ctx, T.grassTop, [96, 154, 68], 9, 11)
  speckles(ctx, T.grassTop, 18, 12, [
    [78, 134, 54],
    [112, 172, 80],
    [86, 144, 60],
  ])
  speckles(ctx, T.grassTop, 6, 13, [[124, 184, 92]], 1, 1)

  // 1 — grass side
  paintBase(ctx, T.grassSide, [120, 86, 54], 12, 21)
  const fringeRand = mulberry32(22)
  for (let x = 0; x < TILE; x++) {
    const depth = 3 + Math.floor(fringeRand() * 3)
    for (let y = 0; y < depth; y++) {
      const c = y === depth - 1 ? [68, 132, 44] : [88, 160, 60]
      pixel(ctx, T.grassSide, x, y, shade(c, (fringeRand() - 0.5) * 18))
    }
  }
  speckles(ctx, T.grassSide, 16, 23, [[96, 66, 40], [146, 105, 66]])

  // 2 — dirt
  paintBase(ctx, T.dirt, [126, 88, 56], 14, 31)
  speckles(ctx, T.dirt, 18, 32, [[104, 70, 42], [146, 104, 66]], 1, 2)

  // 3 — stone
  paintBase(ctx, T.stone, [130, 134, 140], 8, 41)
  speckles(ctx, T.stone, 14, 42, [[112, 116, 122], [148, 152, 158]], 1, 2)
  const crack = mulberry32(43)
  for (let i = 0; i < 3; i++) {
    let x = 2 + Math.floor(crack() * 11)
    let y = 2 + Math.floor(crack() * 9)
    for (let j = 0; j < 4; j++) {
      pixel(ctx, T.stone, x, y, [96, 101, 108])
      x += crack() > 0.5 ? 1 : 0
      y += 1
    }
  }

  // 4 — sand
  paintBase(ctx, T.sand, [220, 205, 152], 8, 51)
  speckles(ctx, T.sand, 20, 52, [[206, 188, 134], [236, 222, 176]], 1, 1)

  // 5 — snow
  paintBase(ctx, T.snow, [238, 246, 252], 4, 61)
  speckles(ctx, T.snow, 12, 62, [[224, 238, 250], [252, 254, 255]], 1, 1)

  // 6 — log side
  paintBase(ctx, T.logSide, [106, 76, 46], 8, 71)
  const barkRand = mulberry32(72)
  for (let x = 0; x < TILE; x++) {
    if (x % 4 === 1) {
      for (let y = 0; y < TILE; y++) {
        if (barkRand() > 0.12) pixel(ctx, T.logSide, x, y, [78, 52, 28])
      }
    } else if (x % 4 === 3) {
      for (let y = 0; y < TILE; y++) {
        if (barkRand() > 0.5) pixel(ctx, T.logSide, x, y, [132, 96, 58])
      }
    }
  }

  // 7 — log top
  paintBase(ctx, T.logTop, [158, 120, 74], 10, 81)
  for (let y = 0; y < TILE; y++) {
    for (let x = 0; x < TILE; x++) {
      const d = Math.max(Math.abs(x - 7.5), Math.abs(y - 7.5))
      const ring = Math.floor(d)
      if (ring % 2 === 0) pixel(ctx, T.logTop, x, y, [122, 88, 52])
      if (d < 1.5) pixel(ctx, T.logTop, x, y, [92, 64, 38])
    }
  }
  rect(ctx, T.logTop, 7, 7, 2, 2, [84, 57, 32])

  // 8 — leaves
  paintBase(ctx, T.leaves, [62, 118, 50], 18, 91)
  speckles(ctx, T.leaves, 30, 92, [
    [42, 92, 36],
    [76, 140, 58],
    [96, 158, 68],
  ], 1, 2)
  const holes = mulberry32(93)
  ctx.save()
  ctx.globalCompositeOperation = 'destination-out'
  for (let i = 0; i < 10; i++) {
    const x = Math.floor(holes() * TILE)
    const y = Math.floor(holes() * TILE)
    ctx.fillStyle = 'rgba(0,0,0,1)'
    ctx.fillRect(tileOrigin(T.leaves).x + x, tileOrigin(T.leaves).y + y, 1 + (holes() > 0.75 ? 1 : 0), 1)
  }
  ctx.restore()

  // 9 — planks
  paintBase(ctx, T.planks, [174, 132, 80], 7, 101)
  for (let y = 0; y < TILE; y++) {
    if (y % 4 === 3) {
      for (let x = 0; x < TILE; x++) pixel(ctx, T.planks, x, y, [118, 84, 46])
    }
  }
  const grain = mulberry32(102)
  for (let i = 0; i < 14; i++) {
    const x = Math.floor(grain() * 14)
    const y = Math.floor(grain() * 15)
    rect(ctx, T.planks, x, y, 2 + Math.floor(grain() * 4), 1, [150, 108, 60])
  }
  rect(ctx, T.planks, 3, 0, 1, 3, [132, 94, 52])
  rect(ctx, T.planks, 11, 8, 1, 3, [132, 94, 52])

  // 10 — cobblestone
  paintBase(ctx, T.cobble, [122, 127, 133], 10, 111)
  const cob = mulberry32(112)
  const stones = [
    [1, 1, 6, 4],
    [9, 1, 5, 5],
    [1, 7, 5, 3],
    [7, 7, 4, 3],
    [12, 7, 3, 5],
    [1, 12, 6, 3],
    [9, 12, 6, 3],
    [12, 2, 3, 3],
  ]
  for (const [x, y, w, h] of stones) {
    const base = [116 + Math.floor(cob() * 30), 120 + Math.floor(cob() * 30), 126 + Math.floor(cob() * 30)]
    rect(ctx, T.cobble, x, y, w, h, base)
    rect(ctx, T.cobble, x, y, w, 1, shade(base, 18))
    rect(ctx, T.cobble, x, y + h - 1, w, 1, shade(base, -22))
  }

  // 11 — glass
  rect(ctx, T.glass, 0, 0, 16, 16, [186, 226, 242], 0.08)
  for (let x = 0; x < TILE; x++) {
    pixel(ctx, T.glass, x, 0, [206, 238, 250], 0.62)
    pixel(ctx, T.glass, x, 15, [206, 238, 250], 0.62)
    pixel(ctx, T.glass, 0, x, [206, 238, 250], 0.62)
    pixel(ctx, T.glass, 15, x, [206, 238, 250], 0.62)
  }
  for (let i = 0; i < 5; i++) {
    pixel(ctx, T.glass, 3 + i, 10 - i, [255, 255, 255], 0.35)
    pixel(ctx, T.glass, 4 + i, 10 - i, [255, 255, 255], 0.18)
  }
  pixel(ctx, T.glass, 4, 4, [255, 255, 255], 0.28)
  pixel(ctx, T.glass, 11, 12, [255, 255, 255], 0.2)

  // 12 — bricks
  rect(ctx, T.brick, 0, 0, 16, 16, [190, 174, 152])
  const brickRand = mulberry32(121)
  for (let row = 0; row < 4; row++) {
    const offset = row % 2 === 0 ? 0 : 4
    for (let col = -1; col < 3; col++) {
      const x = col * 8 + offset
      const y = row * 4
      const c = [158 + Math.floor(brickRand() * 18), 66 + Math.floor(brickRand() * 16), 50 + Math.floor(brickRand() * 12)]
      rect(ctx, T.brick, x + 1, y + 1, 6, 2, c)
      rect(ctx, T.brick, x + 1, y + 1, 6, 1, shade(c, 16))
