.pause-inner h2 {
  margin: 0;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 46px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-shadow: 0 4px 0 rgba(0, 0, 0, 0.35);
}

.pause-sub {
  margin: 4px 0 20px;
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.pause-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.pause-actions .btn {
  width: 100%;
  flex: none;
}

.sens-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 20px;
  color: var(--muted);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-align: left;
}

input[type="range"] {
  width: 100%;
  height: 4px;
  appearance: none;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  border: 2px solid #0d1a11;
  background: var(--green);
  box-shadow: 0 0 0 3px rgba(126, 217, 87, 0.2);
  cursor: pointer;
}

.pause-hint {
  margin: 18px 0 0;
  color: #778a96;
  font-size: 10.5px;
}

/* ---------------- loading ---------------- */

#loading {
  z-index: 40;
  background:
    radial-gradient(80% 60% at 50% 40%, rgba(29, 55, 36, 0.55), transparent 70%),
    linear-gradient(160deg, #0c1a14, #0a1119 55%, #080d13);
}

.loader {
  width: min(420px, 84vw);
  text-align: center;
}

.loader-mark {
  width: 54px;
  height: 54px;
  margin: 0 auto 20px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  transform: rotate(45deg);
  animation: loader-spin 3.4s linear infinite;
}

.loader-mark span {
  border-radius: 3px;
  background: linear-gradient(140deg, #9cf07a, #4c9e34);
  box-shadow: 0 0 18px rgba(126, 217, 87, 0.25);
}

.loader-mark span:nth-child(2) {
  opacity: 0.55;
}
.loader-mark span:nth-child(3) {
  opacity: 0.75;
}
.loader-mark span:nth-child(4) {
  opacity: 0.35;
}

@keyframes loader-spin {
  to {
    transform: rotate(405deg);
  }
}

.loader-title {
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 34px;
  letter-spacing: 0.12em;
  color: #f2f8f4;
}

.loader-bar {
  position: relative;
  height: 7px;
  margin: 20px 0 12px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
}

.loader-bar i {
  display: block;
  width: 0%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #4f9f37, #8fe76a);
  box-shadow: 0 0 16px rgba(126, 217, 87, 0.5);
  transition: width 0.25s ease;
}

.loader-text {
  color: #8fa39a;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.08em;
}

/* ---------------- HUD ---------------- */

#hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s;
}

#hud.is-active {
  opacity: 1;
  visibility: visible;
}

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 36px;
  height: 36px;
  margin: -18px 0 0 -18px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.85));
}

.ch-dot,
.ch-dot::before,
.ch-dot::after {
  position: absolute;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 1px;
}

.ch-dot {
  width: 4px;
  height: 4px;
}

.ch-dot::before,
.ch-dot::after {
  content: "";
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.ch-dot::before {
  width: 14px;
  height: 2px;
}

.ch-dot::after {
  width: 2px;
  height: 14px;
}

.ch-ring {
  position: absolute;
  inset: 0;
  width: 36px;
  height: 36px;
  transform: rotate(-90deg);
  opacity: 0;
  transition: opacity 0.1s;
}

.ch-ring circle {
  fill: none;
  stroke: var(--amber);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  filter: drop-shadow(0 0 4px rgba(255, 200, 87, 0.8));
}

#crosshair.is-mining .ch-ring {
  opacity: 1;
}

#crosshair.is-mining .ch-dot {
  background: var(--amber);
}

.hud-chip {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 9px;
  height: 30px;
  padding: 0 11px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  background: rgba(7, 13, 19, 0.52);
  color: #dce8f0;
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.02em;
  backdrop-filter: blur(10px);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
}

#hudTopLeft {
  left: calc(12px + var(--safe-l));
  top: calc(12px + var(--safe-t));
  z-index: 3;
}

#hudTopRight {
  right: calc(12px + var(--safe-r));
  top: calc(12px + var(--safe-t));
  z-index: 3;
  pointer-events: auto;
}

.hud-sep {
  width: 1px;
  height: 12px;
  background: rgba(255, 255, 255, 0.18);
}

#biomeText {
  color: var(--green);
}

.hud-icon-btn {
  display: none;
  width: 24px;
  height: 24px;
  margin-right: -5px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
  color: #dce8f0;
  cursor: pointer;
}

.hud-icon-btn svg {
  width: 14px;
  height: 14px;
  fill: currentColor;
}

#toast {
  position: absolute;
  left: 50%;
  bottom: calc(98px + var(--safe-b));
  transform: translate(-50%, 8px);
  padding: 8px 14px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 9px;
  background: rgba(8, 14, 20, 0.78);
  color: #f1f6fa;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
  backdrop-filter: blur(10px);
  white-space: nowrap;
}

#toast.is-on {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

#hotbar {
  position: absolute;
  left: 50%;
  bottom: calc(14px + var(--safe-b));
  transform: translateX(-50%);
  display: flex;
  gap: 5px;
  padding: 6px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 13px;
  background: rgba(7, 13, 19, 0.62);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(12px);
  pointer-events: auto;
}

.slot {
  position: relative;
  width: 52px;
  height: 52px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.045);
  cursor: pointer;
  transition: transform 0.12s ease, border-color 0.12s, background 0.12s;
  overflow: hidden;
}

.slot canvas {
  position: absolute;
  inset: 5px;
  width: calc(100% - 10px);
  height: calc(100% - 10px);
  image-rendering: pixelated;
}

.slot .slot-key {
  position: absolute;
  left: 4px;
  top: 3px;
  color: rgba(255, 255, 255, 0.55);
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1;
}

.slot:hover {
  background: rgba(255, 255, 255, 0.1);
}

.slot.is-selected {
  border-color: rgba(255, 255, 255, 0.85);
  background: rgba(255, 255, 255, 0.14);
  box-shadow: 0 0 0 2px rgba(126, 217, 87, 0.55), 0 6px 18px rgba(0, 0, 0, 0.35);
  transform: translateY(-3px);
}

#debug {
  position: absolute;
  left: calc(12px + var(--safe-l));
  top: calc(50px + var(--safe-t));
  max-width: min(360px, 70vw);
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9px;
  background: rgba(5, 10, 15, 0.8);
  color: #b8e6a0;
  font-family: var(--mono);
  font-size: 10.5px;
  line-height: 1.65;
  white-space: pre;
  display: none;
  backdrop-filter: blur(10px);
}

#debug.is-on {
  display: block;
}

/* ---------------- touch ---------------- */

#mobileControls {
  display: none;
  position: absolute;
  inset: 0;
}

body.is-touch #mobileControls {
  display: block;
}

body.is-touch #hudTopLeft {
  font-size: 9.5px;
}

body.is-touch .hud-icon-btn {
  display: grid;
  place-items: center;
}

body.is-touch #hotbar {
  bottom: calc(10px + var(--safe-b));
  gap: 4px;
  padding: 5px;
}

body.is-touch .slot {
  width: 43px;
  height: 43px;
}

body.is-touch #toast {
  bottom: calc(118px + var(--safe-b));
}

#joystick {
  position: absolute;
  left: calc(22px + var(--safe-l));
  bottom: calc(92px + var(--safe-b));
  width: 116px;
  height: 116px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.24);
  background: radial-gradient(circle at 50% 45%, rgba(255, 255, 255, 0.13), rgba(8, 14, 20, 0.36));
  box-shadow: inset 0 0 30px rgba(0, 0, 0, 0.28);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(8px);
}

#joystick::before,
#joystick::after {
  content: "";
  position: absolute;
  background: rgba(255, 255, 255, 0.12);
}

#joystick::before {
  left: 50%;
  top: 12%;
  bottom: 12%;
  width: 1px;
}

#joystick::after {
  top: 50%;
  left: 12%;
  right: 12%;
  height: 1px;
}

#stick {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 50px;
  height: 50px;
  margin: -25px 0 0 -25px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.5);
  background: radial-gradient(circle at 40% 32%, rgba(255, 255, 255, 0.32), rgba(180, 210, 190, 0.12));
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.32);
  transition: transform 0.06s linear;
}

#lookZone {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 150px;
  width: 55%;
  pointer-events: auto;
  touch-action: none;
}

#touchActions {
  position: absolute;
  right: calc(16px + var(--safe-r));
  bottom: calc(86px + var(--safe-b));
  display: grid;
  grid-template-columns: repeat(2, 58px);
  gap: 10px;
  pointer-events: none;
}

.touch-btn {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border: 1.5px solid rgba(255, 255, 255, 0.28);
  border-radius: 50%;
  background: rgba(9, 16, 23, 0.42);
  color: #eef7f2;
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(8px);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
  transition: transform 0.1s, background 0.1s;
}

.touch-btn svg {
  width: 26px;
  height: 26px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.touch-btn.is-down {
  transform: scale(0.93);
  background: rgba(126, 217, 87, 0.32);
  border-color: rgba(126, 217, 87, 0.8);
}

.touch-mine {
  grid-column: 1;
  grid-row: 2;
  width: 68px;
  height: 68px;
  margin: -4px 0 0 -4px;
  background: rgba(58, 44, 24, 0.46);
}

.touch-place {
  grid-column: 2;
  grid-row: 2;
  background: rgba(24, 44, 58, 0.46);
}

.touch-jump {
  grid-column: 1 / span 2;
  justify-self: end;
  width: 58px;
  height: 58px;
}

.touch-fly {
  grid-column: 2;
  grid-row: 3;
  width: 46px;
  height: 46px;
  justify-self: start;
  margin-left: -54px;
  opacity: 0.9;
}

.touch-inv {
  grid-column: 1;
  grid-row: 3;
  width: 46px;
  height: 46px;
  opacity: 0.9;
}

/* ---------------- inventory ---------------- */

#inventory {
  z-index: 35;
}

#inventory .inv-inner {
  position: relative;
  width: min(760px, 92vw);
  max-height: 88vh;
  display: flex;
  flex-direction: column;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--panel-strong);
  box-shadow: var(--shadow);
  backdrop-filter: blur(20px);
  animation: menu-in 0.3s ease both;
}

.inv-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
}

.inv-head h2 {
  margin: 0;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 30px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.inv-head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 11.5px;
}

.inv-close {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--ink);
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
}

.inv-close:hover {
  background: rgba(255, 255, 255, 0.12);
}

.inv-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(84px, 1fr));
  gap: 9px;
  padding: 16px 2px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.inv-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 6px 8px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.035);
  color: #cfdde6;
  font-size: 9.5px;
  text-align: center;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.15s;
}

.inv-item:hover {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(126, 217, 87, 0.5);
  transform: translateY(-2px);
}

.inv-item canvas {
  width: 52px;
  height: 52px;
  image-rendering: pixelated;
}

.inv-item.is-current {
  border-color: var(--amber);
  background: rgba(255, 200, 87, 0.1);
}

.inv-foot {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.09);
  color: #81939f;
  font-size: 10px;
}

/* ---------------- responsive ---------------- */

@media (max-width: 760px) {
  .menu-inner {
    gap: 14px;
    padding: 10px;
    justify-content: center;
  }

  .menu-header {
    margin-top: 0;
  }

  .logo {
    font-size: clamp(44px, 15vw, 74px);
  }

  .tagline {
    margin-top: 8px;
    font-size: 10px;
    letter-spacing: 0.22em;
  }

  .menu-panel {
    padding: 14px;
  }

  .controls-card {
    display: none;
  }

  .menu-footer {
    font-size: 9px;
  }

  .menu-footer span:last-child {
    display: none;
  }

  .pause-inner {
    padding: 20px;
  }

  .inv-grid {
    grid-template-columns: repeat(auto-fill, minmax(72px, 1fr));
  }

  #debug {
    display: none !important;
  }
}

@media (max-height: 620px) {
  .menu-header {
    display: none;
  }

  .controls-card {
    display: none;
  }

  .menu-inner {
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
